class GroupContainer(CodeContainer):
    """
    A GroupContainer is made from a group instruction and potentially holds
    several other containers inside. The grouping might only be symbolically.
    Head and Foot are not occupyable by anything other than formal block
    delimiters and comments.
    """


class CodeBlock(GroupContainer):
    """A block of code that can only contain codelines but no control structures"""

    # should default to getting the content of body without any extras.
    def append(self, content):
        """append a container to the body"""
        if not isinstance(content, (CodeLine, CodeBlock)):
            raise TypeError("Can only add CodeLine leaf nodes to CodeBlock")
            # if a codeblock is added, it can only have codelines in it.
            # or codeblocks, but those can only contain codelinexs themselves.
            # or codeblocks, but those can only contain codelines themselves.
            # ...
            # you get it.
        super().append(content)


class CodeLine(CodeContainer):
    """Recursion-Breaking. Literally a single line."""

    def __init__(self, line, context, **params):
        super().__init__(context=context, **params)
        self._line = line

    def get_codelines_body(self, indent, **kwargs):
        for line in self.construct_code_lines(**kwargs):
            yield indent, line

    def get_codelines_head(self, indent, **kwargs):
        return
        yield

    def get_codelines_foot(self, indent, **kwargs):
        return
        yield

    @property
    def line(self):
        """access hidden attribute line"""
        if self._line is None:
            raise ValueError("CodeLine not set!")
        return self._line

    # @line.setter
    # def line(self, line):
    #     """write-access. Maybe disallow in the future."""
    #     self.set_line(line)

    def append_head(self, *_):
        raise ValueError("Cannot append to head in StatementLine")

    def append_body(self, *_):
        raise ValueError("Cannot append to head in StatementLine")

    def append_foot(self, *_):
        raise ValueError("Cannot append to head in StatementLine")

    def set_line(self, line):
        """set the line"""
        if not isinstance(line, str):
            raise TypeError("Line must be a string")
        if "\n" in line:
            raise ValueError("Line cannot contain newline")
        self._line = line
        return self

    def format(self, **replacements):
        """format the line using replacements"""
        self._line = self._line.format(**replacements)

    def construct_code_lines(self, **_):
        """construct the code line"""
        # this is a generator to include line breaks if necessary
        if self._line is not None:
            yield self.line


class StatementLine(CodeLine):
    """
    A statement of form
      output = somefunction(input1, ...)
      output = input[index]
      output = input
      output = input1 some_operator input2

    Serves as base class for more specific statements, but handles the variable
    dependencies
    """

    _BLUEPRINT = ""

    def __init__(self, value_dict, context, **params):
        super().__init__(
            type(self)._BLUEPRINT.format(**value_dict),
            context=context,
            **params,
        )


class CommentLine(CodeLine):
    """
    This line represents a comment
    """

    COMMENT_PREFIX = "#"

    def construct_code_lines(self, **_):
        yield type(self).COMMENT_PREFIX + self.line


class DefinitionLines(CodeLine):
    """
    This line represents a comment
    """

    def __init__(self, variable, context, **params):
        super().__init__(line=None, context=context, **params)
        self.set_variable(variable)

    @property
    def variable(self):
        """acccess variable"""
        return self._variable

    def construct_code_lines(self, **_):
        yield from self._variable.get_definition_lines()

    def set_variable(self, variable):
        """set the variable. Maybe disallow that later."""
        self._variable = variable
        return self


class EnclosingContainer(GroupContainer):
    """
    An Environment block. Opening and closing operators so pairs always match.
    Indent optional. Made for brackets, parenthesis, definitions, ...
    Brackets in brackets are treated, ignored or combined.
    As the group container requires, head and foot are defined by the Enclosing
    class and are not occupied by other content.
    """

    def __init__(self, context, **buildargs) -> None:
        super().__init__(context, **buildargs)

    def set_enclosings(self, head_string, foot_string, **buildargs):
        """this method later defines the enclosing characters."""
        self.append_head(self.from_text(head_string, **buildargs))
        self.append_foot(self.from_text(foot_string, **buildargs))
        return self


class LoopContainer(EnclosingContainer):
    """
    A LoopContainer provides basic loop control capabilities. It can derive into
    different versions depending on the architecture.
    """


class CaptureContainer(CodeContainer):
    """
    Generalization of Definition and Initialization Container, important for class
    hierarchy.
    """

    def __init__(self, context, **buildargs) -> None:
        super().__init__(context=context, **buildargs)
        # new namespace node in capture container
        self._context.new_namespace_node()
        self._filter_func_customs: Set[Callable] = set()
        self._filter_func_captures: Set[str] = set()
        self._provided: Set[LibRoutineVariable] = set()

    def add_capture_trigger(self, capture: str | Callable) -> None:
        """add a type of requirement to capture"""
        if isinstance(capture, str):
            self._filter_func_captures.add(capture)
        elif callable(capture):
            self._filter_func_customs.add(capture)
        else:
            raise ValueError(
                f"Invalid filter arg {capture}. Must be str|callable."
            )

    @property
    def captured(self):
        """get the captured libvariables"""
        yield from self._provided

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        for func in self._filter_func_customs:
            if func(requirement):
                return True
        if requirement.vtype in self._filter_func_captures:
            return True
        return False

    def provides(self, variable):
        """
        This CaptureContainer provides a variable.
        It is also added to the namespace and can be seen from all derived namespaces.
        """
        self._provided.add(variable)
        self.namespace.add(variable)

    def requires(self, variable):
        """send the required variables up the tree"""
        if self.capture_check(variable):
            self.provides(variable)
        else:
            super().requires(variable)

    def build(self):
        """
        builds the capture container, which requires that up to that point
        all potential variables have been captured.
        """
        return self


class DefinitionContainer(CaptureContainer):
    """
    A code container that defines stuff and prevents them from getting passed
    on during requirement iterator. Supports a filtering function that decides
    on which type of requirements are implemented here or passed on.
    """

    def build(self):
        """build head and tail section of the definition container"""
        # append all definition lines in head
        for variable in self.captured:
            self.append_head(
                DefinitionLines(variable, context=self.context.inherit())
            )
        # perform potential allocations in head
        # perform potential deallocations in tail
        return self


class RoutineContainer(EnclosingContainer):
    """
    How a routine is defined, especially handles the section where the arguments
    are passed and opening/enclosing statements.
    """

    # should provide a string how the routine is called
    # should provide a general signature database for imports
    # libraries can provide that and when a library is imported, the
    # signatures are provided


class KernelContainer(RoutineContainer):
    """
    A KernelContainer represents a piece of code that is supposed to be called
    in various memory locations, potentially simultaneously. KernelContainers
    might map to parametrized auxilliary functions or actual kernels on GPUs.

    An instruction block from a map instruction is preferably rendered into a
    kernel. Kernels are treated as subtypes of functions. They provide frame selectors
    and map them to external parallel ressources.

    Kernel Containers provide some management for frame selectors
    """


class LibraryContainer(EnclosingContainer):
    """
    A Library contains routines, constants and more.
    """

    def capture_check(self, requirement):
        """perform a capture check for the requirement"""
        # library level must capture all required variables!
        if requirement.vtype not in ["IMPORT", "CONSTANT"]:
            raise ValueError(
                "only constants are allowed to traverse to library definition level"
            )
        return True


